	// ---- constants lifted from ClubCard.js / ClubCardBuilder.js (R131) -------

	const FAME_GOAL = 100;
	const LEVEL_LIMIT = [0, 5, 7, 13, 20, 40];        // members per club tier
	const LEVEL_COST = [0, 0, 10, 20, 30, 40];        // money to reach tier N
